Procedure bestDay(Z)
    countSat = 0, countSun = 0
    while(Table 1 has more rows){
        Read the first row X from Table 1
        if(X.City == Z){
            countSat = countSat + X.Saturday
            countSun = countSun + X.Sunday
        }
        Move X to Table 2
    }
    if(countSun > countSat){
        return("Sunday")
    }
    return("Saturday")
End bestDay

